/**
 * Post-process the files generated by `pg-schema` so they compile with
 * `verbatimModuleSyntax` (they only ever contain types).
 */
import { readdir, readFile, writeFile } from 'node:fs/promises';

const dir = new URL('../__generated__/', import.meta.url);
for (const name of await readdir(dir)) {
  if (!name.endsWith('.ts')) continue;
  const file = new URL(name, dir);
  const source = await readFile(file, 'utf8');
  const fixed = source
    .replace(/^import (?:type )?(\w+), \{(.+)\} from ('.+')$/gm, 'import type { default as $1, $2 } from $3')
    .replace(/^import (?!type )(\w+ from '.+')$/gm, 'import type $1')
    .replace(/^export default (\w+);$/gm, 'export type { $1 as default };')
    .replace(/^export type \{\s*$/gm, 'export type {');
  if (fixed !== source) await writeFile(file, fixed);
}
